with replacements(category_name, task_no, title, description, instructions) as (
  values
  ('Writing',1,'Write a Product Description','Create a clear, persuasive product description for a reusable water bottle sold by an online store.','Write 120–180 words covering the product features, practical benefits, ideal customer and a clear call to action. Keep the tone professional and easy to scan.'),
  ('Writing',2,'Draft a Short Blog Introduction','Write an engaging introduction for a blog article about practical ways to save money each month.','Write 100–150 words that introduce the topic, identify the reader problem and preview what the article will cover.'),
  ('Writing',3,'Create an Email Newsletter','Prepare a short weekly newsletter for a lifestyle brand that wants to keep subscribers engaged.','Write a subject line and 150–200 words of newsletter copy with one useful tip, one featured item or update, and a clear call to action.'),
  ('Writing',4,'Rewrite a Business Bio','Rewrite a short business biography for a digital services company.','Create a polished 100–150 word company bio explaining what the business does, who it serves and why customers can trust it.'),
  ('Writing',5,'Write Social Media Captions','Create five concise social media captions for a fitness accessories brand.','Write five distinct captions. Each should have a clear message, natural call to action and relevant hashtags without excessive emoji use.'),
  ('Writing',6,'Summarize an Article','Create a concise reader-friendly summary of a provided article.','Summarize the main idea, three important points and the practical takeaway. Do not add facts that are not in the source.'),
  ('Writing',7,'Write a FAQ Answer Set','Create useful answers for frequently asked questions on an online clothing store.','Write answers to five common questions about sizing, delivery, returns, payment and order tracking. Keep each answer short and helpful.'),
  ('Writing',8,'Proofread a Customer Message','Polish a customer-facing message so it is clear, courteous and professional.','Correct grammar, spelling and awkward wording while keeping the original meaning. Return the improved message only.'),
  ('Writing',9,'Create a How-To Guide','Write a simple guide explaining how to organize digital files on a computer.','Create a step-by-step guide with a short introduction, numbered steps and a practical closing tip.'),
  ('Writing',10,'Write a Service Listing','Create a marketplace listing for a reliable virtual assistant service.','Write a service title, short description, key deliverables and a concise call to action. Make the listing realistic and professional.'),
  ('Research',1,'Find Five Local Business Ideas','Research five practical small-business ideas that could serve customers in a local urban market.','For each idea, provide the target customer, problem solved, basic startup needs and why there may be demand. Use credible sources where possible.'),
  ('Research',2,'Compare Two Mobile Apps','Compare two mobile apps that solve a similar problem for consumers.','Compare their main features, pricing model, strengths and weaknesses. Finish with which type of user each app suits best.'),
  ('Research',3,'Research a Target Audience','Build a short research profile for customers likely to buy an everyday consumer product.','Identify likely age range, needs, buying motivations, common objections and useful channels for reaching the audience.'),
  ('Research',4,'Find Reliable Sources','Locate reliable online sources for a short business research assignment.','Provide at least five credible sources and briefly explain what useful information each source contains. Prefer official, academic or established sources.'),
  ('Research',5,'Research Product Competitors','Research three competitors for a consumer product sold online.','For each competitor, record its positioning, notable features, approximate price range and one opportunity for differentiation.'),
  ('Research',6,'Gather Market Facts','Collect a small set of verifiable market facts for a business planning exercise.','Find five useful facts, include the source for each and explain in one sentence why each fact matters to the business.'),
  ('Research',7,'Research Customer Questions','Find common questions customers ask before purchasing an online service.','Identify at least ten recurring questions and group them into themes such as pricing, delivery, quality, support and refunds.'),
  ('Research',8,'Research a Content Topic','Research a topic that could become a useful educational blog post.','Provide the main points readers need to know, three reliable sources and three practical examples that could strengthen the article.'),
  ('Research',9,'Find Business Resources','Find useful online resources for a small business owner.','List five resources covering areas such as registration, marketing, finance, training or customer service and explain the value of each.'),
  ('Research',10,'Research a Competitor Website','Review a competitor website from a customer-experience perspective.','Assess navigation, services, pricing information, calls to action and trust signals. Give three practical improvement opportunities.'),
  ('Data Entry',1,'Enter Product Information','Enter a set of product details into a structured table for an online catalog.','Create or update rows using consistent product names, categories, prices, descriptions and stock information. Check every value before submitting.'),
  ('Data Entry',2,'Organize Contact Records','Organize customer contact records into a clean structured list.','Standardize names, phone numbers and email addresses. Keep one person per row and flag incomplete records instead of guessing.'),
  ('Data Entry',3,'Transcribe Inventory Data','Transcribe inventory figures from a provided source into a digital table.','Enter item names, quantities, unit prices and reference codes exactly as supplied. Double-check numbers and preserve the original meaning.'),
  ('Data Entry',4,'Clean a Customer List','Clean a customer list by identifying duplicate or incomplete entries.','Standardize formatting, identify likely duplicates and flag missing information. Do not invent replacement data.'),
  ('Data Entry',5,'Enter Survey Responses','Enter survey responses into a structured dataset.','Record each response under the correct question or field. Maintain consistent spelling and formatting and avoid changing the respondent meaning.'),
  ('Data Entry',6,'Categorize Expenses','Organize business expense records into consistent categories.','Assign each expense to the most appropriate category, preserve the original amount and date, and flag unclear items for review.'),
  ('Data Entry',7,'Update a Product Catalog','Update product catalog records using newly provided information.','Check product names, descriptions, prices and availability. Keep formatting consistent across all records.'),
  ('Data Entry',8,'Format a Spreadsheet','Format a business spreadsheet so it is clean and easy to review.','Apply consistent headers, number formats, spacing and sorting. Do not change the underlying values.'),
  ('Data Entry',9,'Verify Data Accuracy','Review a dataset for obvious entry errors and inconsistencies.','Compare the entries against the provided source, record any corrections and flag values that cannot be verified.'),
  ('Data Entry',10,'Create a Simple Data Table','Convert a list of business information into a clear structured table.','Use sensible column headings, one record per row and consistent formatting. Check that no source information is lost.'),
  ('AI & Data',1,'Classify Customer Messages','Classify customer messages into predefined support categories.','Assign each message the most appropriate category based only on its content. If a message is ambiguous, flag it for review.'),
  ('AI & Data',2,'Label Sentiment','Label short customer comments by sentiment.','Assign positive, neutral or negative labels using the overall meaning of each comment. Do not infer sentiment from isolated words alone.'),
  ('AI & Data',3,'Extract Key Information','Extract important structured details from short text records.','Return the requested fields exactly as they appear in the source and leave a field blank when the information is not provided.'),
  ('AI & Data',4,'Review AI Responses','Review generated answers for relevance, clarity and factual consistency with the provided prompt.','Mark each response as acceptable or needing review and briefly explain any important issue you identify.'),
  ('AI & Data',5,'Create Text Categories','Group a collection of short text entries into useful topic categories.','Create clear category names, assign each entry to one category and flag entries that do not fit the available categories.'),
  ('AI & Data',6,'Identify Duplicate Text','Find duplicate or near-duplicate entries in a text dataset.','Identify records that contain the same or substantially similar content and report the record references.'),
  ('AI & Data',7,'Summarize Dataset Notes','Summarize notes attached to a small business dataset.','Produce a concise summary of recurring issues, important observations and any data-quality concerns mentioned in the notes.'),
  ('AI & Data',8,'Tag Image Descriptions','Assign relevant tags to written descriptions of images.','Choose accurate descriptive tags based only on the provided descriptions. Avoid assumptions that are not supported by the text.'),
  ('AI & Data',9,'Quality Check AI Labels','Quality-check a set of AI-generated labels against simple labeling rules.','Identify incorrect or inconsistent labels, provide the corrected label and give a short reason for each correction.'),
  ('AI & Data',10,'Create a Data Quality Report','Create a short report describing the quality of a small dataset.','Report missing values, duplicates, inconsistent formats and other obvious issues. Finish with practical cleanup recommendations.'),
  ('Design',1,'Design a Social Media Banner','Create a clean promotional banner for a social media campaign.','Use a clear hierarchy, readable text and suitable spacing. Include the provided brand name, message and call to action.'),
  ('Design',2,'Create a Product Card','Design a reusable product card for an online store.','Include product name, image area, short benefit statement, price area and a clear action button while keeping the layout uncluttered.'),
  ('Design',3,'Design a Simple Flyer','Create a simple flyer for a local service promotion.','Include the service name, key benefits, contact area and call to action. Prioritize readability on a phone screen.'),
  ('Design',4,'Create a Logo Concept','Create a simple logo concept for a modern small business.','Develop a clean concept that works at small sizes. Provide the concept rationale and ensure the design is original.'),
  ('Design',5,'Design an Instagram Post','Create an Instagram post promoting a useful product or service.','Use a strong headline, supporting message and clear call to action. Keep important text readable within a mobile feed.'),
  ('Design',6,'Improve a Landing Page Layout','Improve the visual structure of a simple landing page.','Propose a clearer hierarchy for the headline, benefits, social proof and call to action. Keep the layout practical and easy to scan.'),
  ('Design',7,'Create a Presentation Cover','Design a professional cover slide for a business presentation.','Include the presentation title, organization name and date or subtitle. Use balanced spacing and a polished visual hierarchy.'),
  ('Design',8,'Design an App Screen','Design a simple mobile app screen for a task or productivity feature.','Include the key information, primary action and navigation cues. Prioritize usability and clear hierarchy.'),
  ('Design',9,'Create a Promotional Graphic','Create a promotional graphic for an online campaign.','Highlight the offer, benefit and call to action. Ensure the main message remains clear on both desktop and mobile.'),
  ('Design',10,'Create a Simple Infographic','Create a simple infographic explaining a short process or set of facts.','Use concise text, logical grouping and clear visual hierarchy. Make the information understandable without lengthy paragraphs.'),
  ('Social Media',1,'Create a Weekly Content Plan','Create a seven-day content plan for a small business social media account.','Include one post idea per day, the objective, suggested format and a short caption direction.'),
  ('Social Media',2,'Write Engagement Posts','Write social posts designed to encourage genuine audience interaction.','Create five posts using questions, useful prompts or discussion topics. Avoid misleading engagement bait.'),
  ('Social Media',3,'Create a Product Launch Plan','Create a short social media plan for launching a new product.','Cover pre-launch awareness, launch-day content and follow-up posts with suggested timing and calls to action.'),
  ('Social Media',4,'Analyze Social Comments','Analyze a set of social media comments to identify recurring themes.','Group comments by topic, note positive and negative patterns and suggest practical actions for the brand.'),
  ('Social Media',5,'Create Hashtag Ideas','Develop relevant hashtag ideas for a business campaign.','Provide a balanced mix of broad, niche and brand-specific hashtags. Keep them relevant to the actual content.'),
  ('Social Media',6,'Write Customer Replies','Write professional replies to common customer comments on social media.','Prepare concise responses for questions, compliments, complaints and requests for more information. Keep the tone respectful.'),
  ('Social Media',7,'Build a Campaign Calendar','Build a simple campaign calendar for a one-week promotional campaign.','List the date, platform, content type, message and call to action for each planned post.'),
  ('Social Media',8,'Create Educational Posts','Create a set of educational social posts around a useful topic.','Write five short posts that teach practical information and end with a natural prompt for the audience.'),
  ('Social Media',9,'Review a Social Profile','Review a business social media profile for clarity and customer appeal.','Assess the bio, profile information, content consistency, calls to action and visible trust signals. Suggest improvements.'),
  ('Social Media',10,'Create a Community Post','Create a community-focused post that encourages useful conversation around a brand topic.','Write a friendly post with context, a clear discussion question and a respectful call to participate.')
), numbered as (
  select t.id, c.name as category_name, row_number() over(partition by c.id order by t.created_at, t.id) as task_no
  from public.tasks t
  join public.categories c on c.id = t.category_id
)
update public.tasks t
set title = r.title, description = r.description, instructions = r.instructions
from numbered n
join replacements r on r.category_name = n.category_name and r.task_no = n.task_no
where t.id = n.id;
